        if (args.length != 2) {
            System.err.println("Usage: run.sh <input_file> <output_png>");
            System.exit(2);
            return;
        }

        RendererApplication listener = new RendererApplication(args[0], args[1]);
        JoinableHeadlessApplication application = new JoinableHeadlessApplication(
