                int cx = parseInt(tokens[1], lineNumber, "cx");
                int cy = parseInt(tokens[2], lineNumber, "cy");
                int radius = parseInt(tokens[3], lineNumber, "radius");
                setColor(tokens, 4, lineNumber);
                pixmap.fillCircle(cx, cy, radius);
